#!/usr/bin/env python3
import sys, subprocess, re
from pathlib import Path

if len(sys.argv) < 2:
	sys.exit("build.sh must be called by make, not run directly.")

import env

# Raspberry Pi boot files (u-boot builds, firmware files, config.txt...)
# are generated by repository walt-node-boot (git submodule), in docker
# image "waltplatform/rpi-boot-builder". We tag this image with the commit
# of the submodule, to be sure we use boot files matching this commit.
RPI_BOOT_BUILDER_REPO = Path("walt-node-boot")
RPI_BOOT_BUILDER_IMAGE = "waltplatform/rpi-boot-builder"


def run(cmd, **kwargs):
    print(cmd)
    return subprocess.run(cmd, shell=True, **kwargs)


def git_submodule(*args):
    return subprocess.run(["git", "-C", str(RPI_BOOT_BUILDER_REPO), *args],
                          check=True, capture_output=True,
                          text=True).stdout.strip()


def get_rpi_boot_builder():
    """Return the rpi-boot-builder image matching the submodule commit,
       pulling or building it if needed."""
    if not (RPI_BOOT_BUILDER_REPO / "rpi" / "Dockerfile").exists():
        run(f"git submodule update --init {RPI_BOOT_BUILDER_REPO}", check=True)
    commit = git_submodule("rev-parse", "--short=12", "HEAD")
    dirty = git_submodule("status", "--porcelain", "--", "rpi") != ""
    if dirty:
        # local changes not committed yet: always rebuild
        # (the docker build cache makes it fast if nothing changed)
        image = f"{RPI_BOOT_BUILDER_IMAGE}:{commit}-dirty"
    else:
        image = f"{RPI_BOOT_BUILDER_IMAGE}:{commit}"
        if run(f"docker image inspect {image} >/dev/null 2>&1").returncode == 0:
            return image
        if run(f"docker pull -q {image} >/dev/null 2>&1").returncode == 0:
            return image
    print(f"Building {image} from {RPI_BOOT_BUILDER_REPO}/rpi "
          "(this compiles u-boot, it may take a while).")
    run(f"nice docker build --tag={image} {RPI_BOOT_BUILDER_REPO}/rpi",
        check=True)
    return image


def get_descriptor_of_image(image_name):
    """Return the build descriptor ('<os>.<model>' or 'featured.<name>')
       of an image of this repository, or None."""
    if Path(f"featured/{image_name}/Dockerfile").exists():
        return f"featured.{image_name}"
    if "-" in image_name:
        model_type, os_type = image_name.rsplit("-", 1)
        if Path(f"base/{model_type}/{os_type}/Dockerfile").exists():
            return f"{os_type}.{model_type}"
    return None


def ensure_local_parent_images(dockerfile):
    """Images such as featured/rpi32-rtk-base are based on another image
       of this repository (e.g., 'FROM waltplatform/rpi32-debian:latest').
       If this parent image is not available locally, docker would silently
       pull the version published on the docker hub, which may be outdated.
       So we build it first in this case."""
    text = Path(dockerfile).read_text()
    for image_name in re.findall(r"^FROM\s+waltplatform/([^\s:]+):latest\b",
                                 text, re.MULTILINE):
        descriptor = get_descriptor_of_image(image_name)
        if descriptor is None:
            continue
        image = f"waltplatform/{image_name}:latest"
        inspect = subprocess.run(
                ["docker", "image", "inspect", "--format", "{{.Created}}",
                 image], capture_output=True, text=True)
        if inspect.returncode == 0:
            created = inspect.stdout.strip()[:19].replace("T", " ")
            print(f"Using local parent image {image} (built {created}).")
            print(f"Run 'make build.{descriptor}' first to rebuild it.")
            continue
        print(f"Parent image {image} is missing, building it first.")
        run(f"{sys.executable} build.py {descriptor}", check=True)


def get_build_args(dockerfile):
    text = Path(dockerfile).read_text()
    build_args = ""
    if "RPI_BOOT_BUILDER" in text:
        build_args += f" --build-arg RPI_BOOT_BUILDER={get_rpi_boot_builder()}"
    for name, version in env.PINNED_VERSIONS.items():
        if re.search(rf"^ARG\s+{name}\s*$", text, re.MULTILINE):
            build_args += f" --build-arg {name}={version}"
    return build_args


image_descriptor = sys.argv[1].split('.')

if image_descriptor[0] == 'featured':
    name = image_descriptor[1]
    src_dir = f"featured/{name}"
    dockerfile = f"{src_dir}/Dockerfile"
    ensure_local_parent_images(dockerfile)
    build_args = f'--build-arg SRC_DIR="{src_dir}"'
    build_args += get_build_args(dockerfile)
    run(f'nice docker build {build_args} \
        -f {dockerfile} \
        --tag=waltplatform/{name}:latest .',
        check=True)
else:
    os_type, model_type = image_descriptor
    os_version = env.OS_VERSIONS[os_type]
    dockerfile = f"base/{model_type}/{os_type}/Dockerfile"

    build_args=f"--build-arg OS_TYPE={os_type} --build-arg OS_VERSION={os_version}"

    # rpi model is more complex
    if model_type == "rpi32":
        build_args += f" --build-arg KERNEL_ARCHIVE={env.KERNEL_ARCHIVE} \
                         --build-arg KERNEL_VERSION={env.KERNEL_VERSION}"

    build_args += get_build_args(dockerfile)

    # docker build
    run(f'nice docker build {build_args} \
            -f {dockerfile} \
            --tag=waltplatform/{model_type}-{os_type}:latest .',
            check=True)

    # add another docker tag indicating version
    subprocess.run(f'docker tag waltplatform/{model_type}-{os_type}:latest \
            waltplatform/{model_type}-{os_type}:{os_version}',
            check=True, shell=True)
